 value * 2;  // 0 to 1\n          return [255 - 255 * t, 255 - 220 * t, 255 - 113 * t];\n        } else {\n          const t = (value - 0.5) * 2;  // 0 to 1\n          return [0 + 255 * t, 35 - 35 * t, 142 - 142 * t];\n        }\n      },\n\n      filled: true,\n      stroked: false,\n      pickable: true,\n    })\n\n    // Create the deck.gl visualization\n    const deckgl = new DeckGL({\n      controller: true,\n      mapStyle: \'https://basemaps.cartocdn.com/gl/positron-nolabels-gl-style/style.json\',\n      initialViewState: { longitude: 2.35, latitude: 48.85, zoom: 10 },\n      layers: [restaurants],\n      getTooltip: ({object}) => object && `${object.count} restaurants`\n    });\n  <\/script>\n</body>\n</html>\n'})}),"\n",(0,s.jsx)(t.h2,{id:"next-steps",children:"Next Steps"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsx)(t.li,{children:"Try different resolutions (13-17) to see different levels of aggregation"}),"\n",(0,s.jsx)(t.li,{children:"Apply this pattern to other Overture Maps datasets (buildings, cities, etc.)"}),"\n",(0,s.jsx)(t.li,{children:"Try combining multiple datasets, JOINing them by the A5 cell id"}),"\n"]})]})}function v(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(y,{...e})}):y(e)}},1515(e,t,n){var a=n(730);const s={name:"Hyparquet",id:"hyparquet",module:"hyparquet",version:"1.0.0",extensions:["parquet"],mimeTypes:["application/octet-stream"],category:"table",parse:async e=>new Promise((t,n)=>{try{(0,a.bA)({file:e,rowFormat:"object",onComplete:e=>t(e)})}catch(s){n(s)}})};n.d(t,["$",0,s])},4683(e,t,n){function a(e){return BigInt(`0x${e}`)}function s(e){return e.toString(16)}n.d(t,{G:()=>a,K:()=>s})},9477(e,t,n){n.d(t,{A:()=>u});var a=n(4402),s=n(7275);const r={...s.A.defaultProps};class i extends a.A{indexToBounds(){return null}renderLayers(){const{elevationScale:e,extruded:t,wireframe:n,filled:a,stroked:r,lineWidthUnits:i,lineWidthScale:l,lineWidthMinPixels:o,lineWidthMaxPixels:d,lineJ